args.sparql:
SELECT ?person ?personLabel
WHERE {
  ?person wdt:P106 wd:Q4203130 ;  
          wdt:P21 wd:Q6581072 ;  
          wdt:P541 ?season .     
  ?season wdt:P177 wd:Q58455326 ;
          wdt:P585 ?seasonDate .
  FILTER (YEAR(?seasonDate) = 2019)
  ?teamWeek wdt:P166 ?person .    
  FILTER (CONTAINS(LCASE(STR(?teamWeek)), "nissan net points team of the week"))
}
GROUP BY ?person
HAVING (COUNT(?teamWeek) = 10)

SELECT ?person ?personLabel
WHERE {
  ?awards wdt:P1215 ?awardsName  ;
          wdt:P166 ?person .
  FILTER (CONTAINS(LCASE(?awardsName), 'nissan net points team of the week'))

  ?season wdt:P177 wd:Q58455326 ;
          wdt:P585 ?seasonDate .
  FILTER (YEAR(?seasonDate) = 2019)
  ?person wdt:P541 ?season .

  ?person wdt:P21 wd:Q6581072 ;
          wdt:P195 wd:Q152949 .
}
GROUP BY ?person
HAVING (COUNT(?awards) = 10)

SELECT ?person ?personLabel
WHERE {
  ?award wdt:P177 wd:Q58455326 ;
         rdfs:label ?awardLabel ;
         wdt:P585 ?awardDate .
  FILTER (CONTAINS(LCASE(?awardLabel), "nissan net points team of the week"))
  FILTER (LANG(?awardLabel) = "en")
  FILTER (YEAR(?awardDate) = 2019)

  ?person wdt:P166 ?award ;
          wdt:P21 wd:Q6581072 ;
          wdt:P39 wd:Q5484556 .
  ?person rdfs:label ?personLabel .
  FILTER (LANG(?personLabel) = "en")
}
GROUP BY ?person ?personLabel
HAVING (COUNT(?award) = 10)

